print_formats.css:
*{box-sizing:border-box} body{font-family:'Segoe UI',Roboto,Arial,sans-serif;font-size:13px;color:#111;margin:0;padding:24px}
.head{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:2px solid #c1121f;padding-bottom:12px;margin-bottom:16px}
.brand{font-size:22px;font-weight:700;color:#c1121f;letter-spacing:.5px}
.sub{font-size:11px;color:#555;margin-top:2px;line-height:1.5}
.title{font-size:17px;font-weight:700;text-transform:uppercase;text-align:right}
.no{font-size:12px;color:#555;text-align:right;margin-top:2px}
.grid{display:grid;grid-template-columns:1fr 1fr;gap:6px 24px;margin-bottom:14px}
.row{display:flex;gap:8px} .row b{min-width:110px;color:#555;font-weight:600}
table{width:100%;border-collapse:collapse;margin-top:8px} th,td{border:1px solid #ccc;padding:6px 8px}
th{background:#f3f4f6;font-size:11px;text-transform:uppercase;letter-spacing:.3px;text-align:left}
td.n,th.n{text-align:right;font-variant-numeric:tabular-nums}
.tot{margin-top:12px;margin-left:auto;width:290px}
.tot .row{justify-content:space-between;padding:5px 0;border-bottom:1px dashed #ddd}
.tot .big{font-size:16px;font-weight:700;color:#c1121f;border-bottom:none}
.sign{display:flex;justify-content:space-between;margin-top:36px;text-align:center}
.sign div{width:30%} .sign b{display:block;margin-bottom:52px;font-size:12px}
.note{margin-top:14px;font-size:11px;color:#555;white-space:pre-wrap}

